<?php
require_once __DIR__.'/includes/bootstrap.php';require_admin();$pageTitle='User Accounts';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='create'){$name=trim((string)($_POST['name']??''));$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$role=$_POST['role']??'cashier';if($name===''||!preg_match('/^[A-Za-z0-9_.-]{3,60}$/',$username)||strlen($password)<10||!in_array($role,['admin','cashier'],true))throw new RuntimeException('Use a name, username of 3–60 letters/numbers/._-, password of at least 10 characters, and valid role.');$stmt=$pdo->prepare('INSERT INTO users(name,username,password_hash,role) VALUES(?,?,?,?)');$stmt->execute([$name,$username,password_hash($password,PASSWORD_DEFAULT),$role]);$id=(int)$pdo->lastInsertId();log_action($pdo,'create','user',$id,$username);flash('success','User account created.');}elseif($action==='toggle'){$id=(int)($_POST['id']??0);if($id===(int)$_SESSION['user_id'])throw new RuntimeException('You cannot deactivate your own account.');$pdo->prepare('UPDATE users SET active=IF(active=1,0,1) WHERE id=?')->execute([$id]);log_action($pdo,'toggle_account','user',$id);flash('success','Account status updated.');}}catch(Throwable $ex){flash('error',$ex instanceof PDOException?'Could not save. The username may already exist.':$ex->getMessage());}header('Location: users.php');exit;}
$users=$pdo->query('SELECT id,name,username,role,active,created_at FROM users ORDER BY id')->fetchAll();require __DIR__.'/includes/header.php';
?>
<div class="dashboard-grid"><div class="panel"><div class="panel-heading"><div><h3>Create user account</h3><p>Give each staff member an individual login.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create"><div class="field"><label>Full name *</label><input name="name" required maxlength="120"></div><div class="field"><label>Username *</label><input name="username" required minlength="3" maxlength="60" pattern="[A-Za-z0-9_.-]+" autocomplete="off"></div><div class="field"><label>Temporary password *</label><input type="password" name="password" required minlength="10" autocomplete="new-password"><small class="form-help">At least 10 characters.</small></div><div class="field"><label>Role</label><select name="role"><option value="cashier">Cashier</option><option value="admin">Admin / Store owner</option></select></div><div class="field field-action"><button class="btn primary">Create account</button></div></form></div><div class="panel"><div class="panel-heading"><div><h3>Access roles</h3><p>Limit access to business-critical actions.</p></div></div><div class="info-card"><span class="stat-icon orange">A</span><strong>Admin / Store owner</strong><p>Manage products, archive items, void sales, and create accounts.</p></div><div class="info-card"><span class="stat-icon blue">C</span><strong>Cashier</strong><p>Process sales and manage day-to-day product and stock operations. Account administration and sale voiding are restricted.</p></div></div></div>
<div class="panel"><div class="panel-heading"><div><h3>Registered users</h3><p><?= count($users) ?> accounts</p></div></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Username</th><th>Role</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php foreach($users as $u): ?><tr><td><strong><?= e($u['name']) ?></strong></td><td><?= e($u['username']) ?><?= (int)$u['id']===(int)$_SESSION['user_id']?' <span class="badge muted-badge">You</span>':'' ?></td><td><?= e(ucfirst($u['role'])) ?></td><td><span class="badge <?= $u['active']?'success':'danger' ?>"><?= $u['active']?'Active':'Inactive' ?></span></td><td><?= date('M j, Y',strtotime($u['created_at'])) ?></td><td><?php if((int)$u['id']!==(int)$_SESSION['user_id']): ?><form method="post" onsubmit="return confirm('Change this account status?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?= (int)$u['id'] ?>"><button class="btn small <?= $u['active']?'danger-outline':'secondary' ?>"><?= $u['active']?'Deactivate':'Activate' ?></button></form><?php else: ?><span class="muted">Current account</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php require __DIR__.'/includes/footer.php'; ?>
